import "dotenv/config";
import { z } from "zod";

const envSchema = z.object({
  RPC_URL: z.string().url(),
});

export const env = envSchema.parse(process.env);

export async function getChainSnapshot(address: string) {
  if (!isAddress(address)) {
    return { ok: false, error: `"${address}" is not a valid address` };
  }
  const [blockNumber, balance] = await Promise.all([
    provider.getBlockNumber(),
    provider.getBalance(address),
  ]);
  return { ok: true, value: { blockNumber, balanceEth: formatEther(balance) } };
}

async function main() {
  const address = process.argv[2];
  if (!address) process.exit(1);

  const result = await getChainSnapshot(address);
  if (!result.ok) {
    console.error(`Error: ${result.error}`);
    process.exit(1);
  }
  console.log(result.value);
}

main().catch((e) => { console.error(e); process.exit(1); });
